import { localeIds, type Locale } from "./locales";

function row(...parts: string[]): Record<Locale, string> {
  const out = {} as Record<Locale, string>;
  localeIds.forEach((id, index) => {
    out[id] = parts[index] ?? parts[0];
  });
  return out;
}

